import {spectralFunction} from './spectral-function.js';
import {spectralFormResearch} from './spectral-form-research.js';
import {editorialNotes} from './spectral-editorial.js';
import {spectralResearch} from './spectral-research.js';
import {spectralConcept} from './spectral-concept.js';
import './spectral-translations.js';
const assets={
 form:'assets/spectral/form-study.png',assembly:'assets/spectral/assembly.png',cover:'assets/spectral/cover.png',product:'assets/spectral/product.png',home:'assets/spectral/home.png',persona:'assets/spectral/persona.png',prototype:'assets/spectral/prototype.png',detail:'assets/spectral/prototype-detail.png',
 current:['assets/spectral/current-1.png','assets/spectral/current-2.png','assets/spectral/current-3.png','assets/spectral/current-4.png','assets/spectral/current-5.png'],
 future:['assets/spectral/future-1.png','assets/spectral/future-2.png','assets/spectral/future-3.png','assets/spectral/future-4.png','assets/spectral/future-5.png','assets/spectral/future-6.png'],
 ritual:['assets/spectral/hold.png','assets/spectral/stay.png','assets/spectral/release.png','assets/spectral/silence.png']
};
const topics=['Product concept','Design context','Form development','Structure & assembly','Slow interaction','Intelligent response','App integration','Final design','User lifecycle','Supporting service','Prototype & development','Reflection'];
export const spectralChapters=[['Cover','case-overview'],...topics.flatMap((t,i)=>[[`${String(i+1+(i>1?1:0)).padStart(2,'0')} / ${t}`,`sf-${String(i+1).padStart(2,'0')}`],...(i===1?[['03 / Concept to design position','sf-concept']]:[])])];
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const img=(src,alt,cls='')=>`<button class="sf-art ${cls}" data-sf-image="${src}" type="button" aria-label="Enlarge ${esc(alt)}"><img src="${src}" alt="${esc(alt)}" loading="lazy" decoding="async"></button>`;
const pills=xs=>`<div class="sf-pills">${xs.map(x=>`<span>${x}</span>`).join('')}</div>`;
const cols=items=>`<div class="sf-columns">${items.map(([title,body],i)=>`<div><span class="sf-number">${String(i+1).padStart(2,'0')}</span><h3>${title}</h3><p>${body}</p></div>`).join('')}</div>`;
const statement=s=>`<p class="sf-statement">${s}</p>`;
function page(n,title,body,cls='',note='Digital Remains · Slow Interaction · Tangible User Interface'){
 const id=String(n).padStart(2,'0'),display=String(n+(n>=3?1:0)).padStart(2,'0');return `<section class="sf-page ${cls} ${![8,12].includes(n)?'sf-editorial-page':''}" id="sf-${id}" aria-labelledby="sf-title-${id}"><div class="sf-masthead"><span class="sf-brand"><i></i>SPECTRAL FLUID</span><span>${display} / ${topics[n-1]}</span></div><header class="sf-heading"><span class="sf-section-label">${topics[n-1]}</span><span class="sf-dash"></span><h2 id="sf-title-${id}">${![8,12].includes(n)?title.replaceAll("<br>"," "):title}</h2>${editorialNotes(n)}</header><div class="sf-content">${body}</div><footer class="sf-footer"><span>${note}</span><span>${display} — ${topics[n-1]}</span></footer></section>`;
}
function blueprint(n,title,stages,rows){
 const names=['User actions','Frontstage','Backstage','Support','Recovery'];const boundaries=['Line of interaction','Line of visibility','Line of internal interaction'];
 return page(n,title,`<div class="sf-blueprint"><table><caption>Proposed service blueprint · ${n===9?'Onboarding':'Continuity and exit'}</caption><thead><tr><th scope="col">Service layer</th>${stages.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map((row,i)=>`<tr><th scope="row">${names[i]}</th>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>${i<3?`<tr class="sf-boundary"><td colspan="5"><span>${boundaries[i]}</span></td></tr>`:''}`).join('')}</tbody></table></div>${statement(n===9?'Trust is built before the first response.':'Non-use is a supported outcome.')}`,'sf-blueprint-page','Proposed service blueprint / '+(n===9?'1':'2')+' of 2');
}
const icon=(kind)=>{
 const paths={trace:'M30 85h80v60H30z M45 103h50 M45 117h40 M145 75a22 22 0 1 0 0 44a22 22 0 1 0 0-44 M145 119v55m0-16h15m-15-10h11',slow:'M55 170V65q45-70 90 0v105 M100 22v85 M80 127a20 20 0 1 0 40 0a20 20 0 1 0-40 0 M35 170h130',touch:'M25 155q18-55 45-29l30 18 30-18q27-26 45 29 M65 146l35 29 35-29 M82 86a18 18 0 1 0 36 0a18 18 0 1 0-36 0 M100 42v-14m-35 26-10-10m80 10 10-10',people:'M77 67a23 23 0 1 0 46 0a23 23 0 1 0-46 0 M50 170v-30q0-40 50-40t50 40v30 M25 80a17 17 0 1 0 34 0a17 17 0 1 0-34 0 M15 155v-22q0-27 30-27 M141 80a17 17 0 1 0 34 0a17 17 0 1 0-34 0 M185 155v-22q0-27-30-27'};
 return `<svg class="sf-line-icon" viewBox="0 0 200 200" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${paths[kind]}"/></svg>`;
};
function phones(){
 const shell=(title,sub,inside,label)=>`<div class="sf-phone-wrap"><div class="sf-phone"><div class="sf-phone-status">9:41 <span>● ▰</span></div><small>SPECTRAL FLUID</small><h3>${title}</h3><p>${sub}</p>${inside}<div class="sf-phone-nav"><span>⌂</span><span>▦</span><span>○</span><span>≡</span></div></div><strong>${label}</strong></div>`;
 return `<div class="sf-phones">${shell('Presence','A quieter way to remember.',`<img class="sf-phone-product" src="${assets.product}" alt="The Spectral Fluid object" loading="lazy"><span class="sf-ui-button sf-ui-dark">Begin a quiet moment →</span><span class="sf-ui-button">Pause</span>`,'Initiate')}${shell('Memory','Personal moments, preserved.',`<div class="sf-phone-tabs">Photos　Audio　Text</div><img class="sf-memory-photo" src="${assets.home}" alt="A remembered afternoon at home" loading="lazy"><b>A quiet afternoon</b><small>Source: personal archive</small><div class="sf-waveform">${Array.from({length:28},(_,i)=>`<i style="height:${[25,65,40,90,55,75,35][i%7]}%"></i>`).join('')}</div><b>A familiar voice</b><small>Source: original recording</small>`,'Curate')}${shell('Ghost','A gentle, abstract presence.',`<div class="sf-orbs"><i></i><i></i><i></i></div><span>Response rhythm</span><div class="sf-ui-range"><i></i></div><span>Intensity</span><div class="sf-ui-range"><i></i></div><div class="sf-generated"><b>AI-generated reflection</b><small>Clearly labeled. No impersonation.</small></div>`,'Adjust')}${shell('Trace','Your reflection.',`<div class="sf-journal"><span>✎</span><p>A place for your own words, after the moment has passed.</p><small>Private by default</small></div><span class="sf-ui-button sf-ui-dark">Save privately</span><small>Only visible to you.</small>`,'Reflect')}</div>`;
}
export function createSpectralFluid({openImage,openGallery}){
 const root=document.createElement('div');root.className='sf-book';
 const intro='Spectral Fluid explores how digital traces can become a quiet, tangible ritual of remembrance. A personal memory archive, a responsive fluid object and a companion app connect meaningful records with everyday life.';
 root.innerHTML=`<section class="sf-page sf-cover-page" id="case-overview" aria-labelledby="sf-cover-title"><img class="sf-cover-background" src="${assets.cover}" width="1876" height="1080" alt="Close detail of the cream Spectral Fluid vessel and its silver fluid surface" fetchpriority="high"><span class="sf-brand sf-cover-brand"><i></i>SPECTRAL FLUID</span><div class="sf-shortcuts"><button type="button" data-sf-jump="sf-04"><img src="${assets.cover}" alt=""><span>Fluid Interface</span></button><button type="button" data-sf-jump="sf-05"><img src="${assets.ritual[0]}" alt=""><span>Slow Interaction</span></button></div><button class="sf-cover-gallery" type="button"><span class="sf-folder"></span>Project Archive</button><div class="sf-cover-bottom"><div class="sf-cover-meta"><span>#Project 03　 #Interaction Design</span><span>Digital Remains / Slow Interaction</span></div><div class="sf-cover-grid"><div><h1 id="sf-cover-title">SPECTRAL<br>FLUID</h1><p class="sf-cover-tagline">A quieter way to remember</p><p class="sf-cover-sub">An interactive intelligent object for remembrance</p></div><div class="sf-cover-copy"><p>${intro}</p><p><strong>Touch, fluid and light</strong> translate selected memories into an abstract physical response. The app supports setup, curation and personal preferences; a complete use journey supports everyday ownership.</p></div></div></div></section>`;
 root.innerHTML+=page(1,'A quieter way<br>to remember.',`<div class="sf-product-intro"><div><span class="sf-pill">Interactive intelligent product</span><p>Touch, responsive fluid and light turn personal memories into a quiet physical experience.</p><h3>Presence, without imitation.</h3><p>The product offers an abstract response, while the app holds records and preferences.</p>${pills(['Tangible interaction','Personal archive','User-controlled pace'])}</div>${img(assets.product,'Spectral Fluid product concept')}<div class="sf-intro-bottom">${img(assets.home,'A quiet domestic setting')}<p>A personal object, supported by a complete journey from first setup to everyday use and eventual exit.</p></div></div>`,'sf-product-introduction');
 root.innerHTML+=spectralResearch(img);
 root.innerHTML+=spectralConcept(img);
 root.innerHTML+=spectralFormResearch(img);
 root.innerHTML+=spectralFunction(img);
 root.innerHTML+=page(5,'A touch. A pause.<br>A moment.',`<div class="sf-ritual">${[['HOLD','Begin by choice.'],['STAY','Let a trace unfold.'],['RELEASE','Allow the response to settle.'],['SILENCE','Return to everyday life.']].map(([h,p],i)=>`<div>${img(assets.ritual[i],h+' — conceptual interaction')}<h3><span>0${i+1}</span> ${h}</h3><p>${p}</p></div>`).join('')}</div>${pills(['Self-initiated','Optional response','User-controlled pace'])}`,'sf-ritual-page','Proposed interaction sequence / generated illustrations');
 root.innerHTML+=page(6,'A deliberate gesture.<br>A restrained response.',`<div class="sf-response-layout">${img(assets.ritual[0],'Holding the interactive object')}<div><span class="sf-pill">Proposed response logic</span>${cols([['Sense','A deliberate touch begins the interaction.'],['Interpret','Use the selected record and the user’s response preferences.'],['Respond','Coordinate fluid movement and light, then settle after release.']])}<div class="sf-flow">Touch <span>→</span> Controller <span>→</span> Fluid + Light</div><p class="sf-response-note">Recorded memories remain distinct from optional AI-generated reflections. No simulated identity; no automatic claim to speak for someone.</p></div></div>`,'sf-product-response','Interaction design / gesture, response and release');
 root.innerHTML+=page(7,'Memories,<br>within reach.',`${phones()}${pills(['Permissions','Export','Delete','Leave service'])}`,'sf-digital','Companion interface / archive, preferences and reflection');
 root.innerHTML+=page(8,'Designed<br>to belong.',`<div class="sf-final-layout"><div class="sf-final-details">${[['Surface','Light held in texture.','top'],['Silhouette','A calm, softened presence.','front'],['Lower edge','A quiet foundation with ventilation.','base']].map(([h,p,c])=>`<div>${img(assets.product,h+' detail','sf-detail-circle sf-detail-'+c)}<div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div>${img(assets.product,'Final product rendering','sf-final-product')}${img(assets.home,'Everyday presence in a home','sf-final-home')}</div>`,'sf-product-final','Final design direction / conceptual renderings');
 root.innerHTML+=page(9,'From first trust<br>to everyday remembrance.',`<div class="sf-storyboard">${[['Discover','Is this right for me?'],['Curate','What belongs here?'],['Set boundaries','What may appear?'],['Begin','Am I ready now?'],['Live with','What pace feels right?'],['Pause or leave','What should remain?']].map(([h,p],i)=>`<div><h3><span>0${i+1}</span> ${h}</h3>${img(assets.future[i],h+' — proposed service scene')}<p>${p}</p></div>`).join('')}</div>`,'sf-future','Proposed service scenario / generated illustrations');
 root.innerHTML+=page(10,'A complete journey.<br>Support when it matters.',`<div class="sf-blueprint"><table><thead><tr><th>Stage</th><th>First setup</th><th>Everyday use</th><th>Pause or leave</th></tr></thead><tbody>${[['User actions','Select memories and pair device','Choose a moment; hold and release','Pause, export or delete'],['Product + app','Preview sources and set preferences','Coordinate response and offer a clear stop','Confirm quiet mode and retention choices'],['Supporting service','Consent records and pairing support','Archive care and device troubleshooting','Export recovery and deletion confirmation']].map(row=>`<tr>${row.map((t,i)=>i?`<td>${t}</td>`:`<th scope="row">${t}</th>`).join('')}</tr>`).join('')}</tbody></table></div>${pills(['Clear provenance','Permissions','Device support','An open exit'])}${statement('The product leads. The service supports continued use.')}`,'sf-blueprint-page','Supporting service proposal');
 root.innerHTML+=page(11,'From working parts<br>to a quiet presence.',`<div class="sf-prototype-grid"><figure>${img(assets.prototype,'Original technical prototype photograph')}<figcaption>Original technical prototype</figcaption></figure><div><div class="sf-prototype-pair">${img(assets.detail,'Original controller and wiring detail')}${img(assets.product,'Proposed enclosure rendering')}</div><div class="sf-iterations">${[['Volume','Compact enclosure'],['Magnetic response','Calibrate force'],['Projection','Refine optical path'],['Heat','Improve ventilation']].map(([a,b])=>`<p><strong>${a}</strong><span>→ ${b}</span></p>`).join('')}</div><div class="sf-flow">Touch <span>→</span> Controller <span>→</span> Fluid + Light</div><p class="sf-validation-note">The prototype brings sensing, fluid actuation and projection together around the rhythm of hold, encounter and release.</p></div></div>`,'sf-prototyping','Original prototype photography / enclosure development');
 root.innerHTML+=page(12,'What should remain?<br>What may fall silent?',`<div class="sf-reflection-copy"><p>Who decides what is remembered?</p><p>How might generated words reshape a memory?</p><p>What remains when the service ends?</p>${statement('The right to remember.<br>The freedom to step away.')}</div>${img(assets.home,'A quiet domestic setting for remembrance','sf-reflection-art')}`,'sf-reflection','SPECTRAL FLUID / A quieter way to remember');
 root.addEventListener('click',e=>{const art=e.target.closest('[data-sf-image]');if(art){openImage([{src:art.dataset.sfImage,name:art.querySelector('img').alt}],0,'SPECTRAL FLUID');return;}const jump=e.target.closest('[data-sf-jump]');if(jump)root.querySelector('#'+jump.dataset.sfJump)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});if(e.target.closest('.sf-cover-gallery'))openGallery('p3');});
 return root;
}

